const routes = {
  home: { path: "/" },
  user: { path: "/users/:id" },
} ____ Record<string, Route>;
```

Type just the keyword.

Many teams replace enums with a const object. What type is `Status` here?

```ts
const Status = { Active: "active", Inactive: "inactive" } as const;
type Status = typeof Status[keyof typeof Status];
```

Which call compiles?

```ts
type UserId = string & { readonly __brand: "UserId" };
type OrderId = string & { readonly __brand: "OrderId" };

function toUserId(s: string): UserId {
  if (!s.startsWith("u_")) throw new Error("bad user id");
  return s as UserId;
}
declare function getUser(id: UserId): void;
