A team adds `{ kind: "idle" }` to this union but forgets to update `render`. What happens?

```ts
type State =
  | { kind: "loading" }
  | { kind: "ok"; data: string }
  | { kind: "error"; message: string };

function render(s: State): string {
  switch (s.kind) {
    case "loading": return "Loading...";
    case "ok": return s.data;
    case "error": return s.message;
    default: {
      const unreachable: never = s;
      return unreachable;
    }
  }
}
```

Which line does the compiler reject?

```ts
type Result<T, E> = { ok: true; value: T } | { ok: false; error: E };

function show(r: Result<number, string>) {
  console.log(r.ok);       // line 1
  console.log(r.value);    // line 2
  if (!r.ok) return r.error; // line 3
  return r.value;          // line 4
}
```

